import type { ComponentProps, CSSProperties, ReactNode } from "react";
import { useState } from "react";
import type { FormSubmitEvent } from "@/components/control-ui/control-props";
import type { ChatDensity } from "@/components/control-ui/hooks/use-chat-message";
import { isComposingKey } from "@/components/control-ui/hooks/use-trigger-menu";
import type { ChatComposerKnobStyle } from "@/components/control-ui/knob-contracts/chat-composer-knobs";

export type ChatComposerSubmitPayload = {
  value: string;
  clear: () => void;
  mentions?: MentionItem[];
};

export type ChatComposerSubmitKey = "enter" | "mod-enter";

export type ChatComposerProps = Omit<ComponentProps<"form">, "onSubmit" | "style"> & {
  children?: ReactNode;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onSubmit?: (payload: ChatComposerSubmitPayload) => void | Promise<void>;
  state?: "idle" | "submitting" | "disabled";
  density?: ChatDensity;
  disabled?: boolean;
  /** Let an empty message send, for composers where an attachment or recording carries the turn. */
  allowEmptySubmit?: boolean;
  submitKey?: ChatComposerSubmitKey;
  style?: CSSProperties & ChatComposerKnobStyle;
};

export type MentionItem = { id: string; label: string; kind: string };

type ComposerKeyEvent = {
  key: string;
  shiftKey: boolean;
  metaKey: boolean;
  ctrlKey: boolean;
  defaultPrevented: boolean;
  nativeEvent: { isComposing: boolean; keyCode: number };
  preventDefault: () => void;
};

type InsertText = (text: string) => void;

export type RegisterInsertionTarget = (insert: InsertText) => () => void;

export type ChatComposerController = {
  value: string;
  setValue: (value: string) => void;
  normalizedValue: string;
  state: NonNullable<ChatComposerProps["state"]>;
  density: ChatDensity;
  submitKey: ChatComposerSubmitKey;
  isCompact: boolean;
  isDisabled: boolean;
  isLocked: boolean;
  canSubmit: boolean;
  rows: number;
  sendCount: number;
  clear: () => void;
  submit: (extra?: Partial<ChatComposerSubmitPayload>) => void;
  handleSubmit: (event: FormSubmitEvent) => void;
  handleKeyDown: (event: ComposerKeyEvent) => void;
  insertText: InsertText;
  registerInsertionTarget: RegisterInsertionTarget;
};

function useControllableText({
  value,
  defaultValue = "",
  onValueChange,
}: Pick<ChatComposerProps, "value" | "defaultValue" | "onValueChange">) {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const isControlled = value !== undefined;
  const currentValue = isControlled ? value : internalValue;

  function setValue(nextValue: string) {
    if (!isControlled) setInternalValue(nextValue);
    onValueChange?.(nextValue);
  }

  return [currentValue, setValue] as const;
}

export function useChatComposer({
  value,
  defaultValue,
  onValueChange,
  onSubmit,
  state = "idle",
  density = "comfortable",
  disabled = false,
  allowEmptySubmit = false,
  submitKey = "enter",
  trackSends = false,
}: Pick<
  ChatComposerProps,
  "value" | "defaultValue" | "onValueChange" | "onSubmit" | "state" | "density" | "disabled" | "allowEmptySubmit" | "submitKey"
> & {
  /** Count successful submits — only enabled when something reads counter (send-layer anchor), so idle apps pay no extra state update. */
  trackSends?: boolean;
}): ChatComposerController {
  const [inputValue, setInputValue] = useControllableText({ value, defaultValue, onValueChange });
  const [sendCount, setSendCount] = useState(0);
  const [insertion] = useState(() => {
    let target: InsertText | null = null;
    const register: RegisterInsertionTarget = (insert) => {
      target = insert;
      return () => {
        if (target === insert) target = null;
      };
    };
    return { register, current: () => target };
  });
  const normalizedValue = inputValue.trim();
  const isDisabled = disabled || state === "disabled";
  const isLocked = state === "submitting";
  const canSubmit = (normalizedValue.length > 0 || allowEmptySubmit) && !isDisabled && !isLocked;
  const isCompact = density === "compact";

  function clear() {
    setInputValue("");
  }

  // shared path: plain textarea via handleSubmit, rich editor calls submit() directly with extras (mentions)
  function submit(extra?: Partial<ChatComposerSubmitPayload>) {
    if (!canSubmit) return;
    if (trackSends) setSendCount((count) => count + 1);
    // onSubmit may return Promise; surface rejected send without unhandled rejection
    Promise.resolve(onSubmit?.({ value: normalizedValue, clear, ...extra })).catch(reportError);
  }

  function handleSubmit(event: FormSubmitEvent) {
    event.preventDefault();
    submit();
  }

  // same contract as the rich editor keymap: the submit key sends, ⌘/Ctrl+Enter always sends, Shift+Enter breaks the line
  function handleKeyDown(event: ComposerKeyEvent) {
    if (event.defaultPrevented || event.key !== "Enter" || event.shiftKey || isComposingKey(event.nativeEvent)) return;
    const modifierHeld = event.metaKey || event.ctrlKey;
    if (submitKey === "mod-enter" && !modifierHeld) return;
    event.preventDefault();
    submit();
  }

  function insertText(text: string) {
    if (isDisabled || isLocked) return;
    const insertAtCaret = insertion.current();
    if (insertAtCaret) insertAtCaret(text);
    else setInputValue(`${inputValue}${text}`);
  }

  return {
    value: inputValue,
    setValue: setInputValue,
    normalizedValue,
    state,
    density,
    submitKey,
    isCompact,
    isDisabled,
    isLocked,
    canSubmit,
    rows: isCompact ? 2 : 4,
    sendCount,
    clear,
    submit,
    handleSubmit,
    handleKeyDown,
    insertText,
    registerInsertionTarget: insertion.register,
  };
}

/*
 * Blur choreography, token-driven (kill-switch collapses to 0).
 * Entry: pill blurs+scales IN via @starting-style (freshly appended by ProseMirror). Exit: pill-delete/message-submit blur OUT via [data-chat-composer-exit] on a throwaway clone (ghost.ts) since ProseMirror removes nodes synchronously.
 * Reads the shared --duration-* and --ease-* tokens.
 */

@layer components {
  /* resting look + blur-IN transition; :not([data-chat-composer-exit] *) excludes exit ghosts/cloned pills from entry choreography */
  :where([data-control-ui="chat-composer"][data-slot="mention"]):not([data-chat-composer-exit]):not([data-chat-composer-exit] *) {
    opacity: 1;
    filter: blur(0);
    scale: 1;
    transition:
      opacity var(--duration-base) var(--ease-emphasized),
      filter var(--duration-base) var(--ease-emphasized),
      scale var(--duration-base) var(--ease-emphasized);
  }

  @starting-style {
    :where([data-control-ui="chat-composer"][data-slot="mention"]):not([data-chat-composer-exit]):not([data-chat-composer-exit] *) {
      opacity: 0;
      filter: blur(6px);
      scale: 0.82;
    }
  }

  /* exit ghost: fixed-position clone, keyframe blurs it out then self-removes on animationend; finite duration lets kill-switch snap it away invisibly */
  :where([data-chat-composer-exit][data-exiting]) {
    opacity: 1;
    filter: blur(0);
    scale: 1;
    translate: 0 0;
    animation: chat-composer-blur-out var(--duration-base) var(--ease-emphasized) forwards;
  }
}

@keyframes chat-composer-blur-out {
  to {
    opacity: 0;
    filter: blur(8px);
    scale: 0.94;
    translate: 0 -0.25rem;
  }
}

"use client";

import { baseKeymap, splitBlock } from "prosemirror-commands";
import { history, redo, undo } from "prosemirror-history";
import { keymap } from "prosemirror-keymap";
import { EditorState, Plugin } from "prosemirror-state";
import { EditorView } from "prosemirror-view";
import { type CSSProperties, useEffect, useMemo, useRef, useState } from "react";

import { useChatComposerContext } from "@/components/control-ui/chat-composer";
import type { ChatComposerSubmitPayload } from "@/components/control-ui/hooks/use-chat-composer";
import type { ChatComposerKnobStyle } from "@/components/control-ui/knob-contracts/chat-composer-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { MESSAGE_GHOST_INHERIT, spawnExitGhost } from "./chat-composer-editor/ghost";
import { createEditorSchema } from "./chat-composer-editor/schema";
import { docFromText, serializeDoc } from "./chat-composer-editor/serialize";
import type { ChatComposerEditorApi, ChatComposerEditorProps } from "./chat-composer-editor/types";

function releaseFileDrag(_view: EditorView, event: DragEvent) {
  return event.dataTransfer ? Array.from(event.dataTransfer.types).includes("Files") : false;
}

/** ProseMirror claims every drag and paste over the editor. A transfer it cannot insert is not editor input, so it has to reach the surrounding drop zone with its default intact. */
const fileTransferPassthrough = {
  dragenter: releaseFileDrag,
  dragover: releaseFileDrag,
  drop: releaseFileDrag,
  paste: (_view: EditorView, event: ClipboardEvent) => {
    const types = event.clipboardData ? Array.from(event.clipboardData.types) : [];
    return types.includes("Files") && !types.includes("text/plain");
  },
};

export function ChatComposerEditor({
  className,
  placeholder,
  style,
  extensions = [],
  "aria-label": ariaLabel = "Message",
  "aria-labelledby": ariaLabelledby,
  "aria-describedby": ariaDescribedby,
}: ChatComposerEditorProps & { style?: CSSProperties & ChatComposerKnobStyle }) {
  const input = useChatComposerContext();

  const mountRef = useRef<HTMLDivElement>(null);
  const viewRef = useRef<EditorView | null>(null);
  const inputRef = useRef(input);
  useEffect(() => {
    inputRef.current = input;
  }, [input]);
  const lastSerialized = useRef(input.value);
  const [mounted, setMounted] = useState(false);
  const [hostAria, setHostAria] = useState<Readonly<Record<string, string>>>({});

  const { isDisabled, isLocked } = input;
  const hostAttributes = useMemo<Record<string, string>>(
    () => ({
      role: "textbox",
      "aria-multiline": "true",
      ...(ariaLabelledby ? { "aria-labelledby": ariaLabelledby } : { "aria-label": ariaLabel }),
      ...(ariaDescribedby ? { "aria-describedby": ariaDescribedby } : {}),
      ...(placeholder ? { "aria-placeholder": placeholder } : {}),
      ...(isDisabled ? { "aria-disabled": "true" } : {}),
      ...(isLocked ? { "aria-readonly": "true", "aria-busy": "true" } : {}),
      ...hostAria,
    }),
    [ariaLabel, ariaLabelledby, ariaDescribedby, placeholder, isDisabled, isLocked, hostAria],
  );
  const hostAttributesRef = useRef(hostAttributes);

  const listenersRef = useRef(new Set<() => void>());
  const keyHandlersRef = useRef(new Set<(event: KeyboardEvent) => boolean>());
  const [api] = useState<ChatComposerEditorApi>(() => ({
    getView: () => viewRef.current,
    subscribe: (listener) => {
      listenersRef.current.add(listener);
      return () => {
        listenersRef.current.delete(listener);
      };
    },
    registerKeyHandler: (handler) => {
      keyHandlersRef.current.add(handler);
      return () => {
        keyHandlersRef.current.delete(handler);
      };
    },
    setHostAria,
  }));
  const [initialExtensions] = useState(extensions);

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;
    const exts = initialExtensions;
    const schema = createEditorSchema(exts);

    const extensionKeymap: Record<string, (typeof baseKeymap)[string]> = {};
    for (const extension of exts) Object.assign(extensionKeymap, extension.keymap?.(schema) ?? {});
    const extensionPlugins = exts.flatMap((extension) => extension.plugins?.(schema, api) ?? []);
    const submitMessage = (editorState: EditorState) => {
      const extra: Partial<ChatComposerSubmitPayload> = {};
      for (const extension of exts) Object.assign(extra, extension.submitPayload?.(editorState.doc) ?? {});
      inputRef.current.submit(extra);
      return true;
    };
    const submitOnEnter = (editorState: EditorState) => inputRef.current.submitKey === "enter" && submitMessage(editorState);

    const state = EditorState.create({
      schema,
      doc: docFromText(schema, inputRef.current.value),
      plugins: [
        new Plugin({
          props: {
            handleKeyDown: (_view, event) => {
              for (const handler of keyHandlersRef.current) if (handler(event)) return true;
              return false;
            },
            handleDOMEvents: fileTransferPassthrough,
          },
          filterTransaction: (transaction) => !transaction.docChanged || !inputRef.current.isLocked,
        }),
        ...extensionPlugins,
        history(),
        keymap(extensionKeymap),
        keymap({
          "Mod-z": undo,
          "Mod-y": redo,
          "Shift-Mod-z": redo,
          "Shift-Enter": splitBlock,
          Enter: submitOnEnter,
          "Mod-Enter": submitMessage,
        }),
        keymap(baseKeymap),
      ],
    });
    const view = new EditorView(mount, {
      state,
      editable: () => !inputRef.current.isDisabled,
      attributes: () => hostAttributesRef.current,
      dispatchTransaction(transaction) {
        const next = view.state.apply(transaction);
        view.updateState(next);
        if (transaction.docChanged) {
          const text = serializeDoc(next.doc);
          lastSerialized.current = text;
          inputRef.current.setValue(text);
        }
        for (const listener of listenersRef.current) listener();
      },
    });
    viewRef.current = view;
    setMounted(true);
    return () => {
      view.destroy();
      viewRef.current = null;
    };
  }, [api, initialExtensions]);

  const { registerInsertionTarget } = input;
  useEffect(
    () =>
      registerInsertionTarget((text) => {
        const view = viewRef.current;
        if (!view) return;
        view.dispatch(view.state.tr.insertText(text));
        view.focus();
      }),
    [registerInsertionTarget],
  );

  useEffect(() => {
    const view = viewRef.current;
    if (!view) return;
    if (input.value === lastSerialized.current) return;
    if (input.value === "" && lastSerialized.current !== "" && view.dom instanceof HTMLElement) {
      spawnExitGhost(view.dom, MESSAGE_GHOST_INHERIT);
    }
    lastSerialized.current = input.value;
    const { schema } = view.state;
    view.updateState(EditorState.create({ schema, doc: docFromText(schema, input.value), plugins: view.state.plugins }));
  }, [input.value]);

  useEffect(() => {
    hostAttributesRef.current = hostAttributes;
    viewRef.current?.setProps({});
  }, [hostAttributes]);

  return (
    <div
      data-control-ui="chat-composer-editor"
      data-control-family="chat-composer"
      data-slot="editor-root"
      style={style}
      className={cn("relative", className)}
    >
      {input.value === "" && placeholder ? (
        <div
          aria-hidden="true"
          data-control-ui="chat-composer-editor"
          data-control-family="chat-composer"
          data-slot="placeholder"
          className="pointer-events-none absolute start-[var(--padding-x)] top-[var(--padding-y)]"
        >
          {placeholder}
        </div>
      ) : null}
      <div
        ref={mountRef}
        data-control-ui="chat-composer-editor"
        data-control-family="chat-composer"
        data-slot="editor"
        className={cn(
          "[&_.ProseMirror]:max-h-[40dvh] [&_.ProseMirror]:min-h-16 [&_.ProseMirror]:w-full [&_.ProseMirror]:overflow-y-auto [&_.ProseMirror]:whitespace-pre-wrap [&_.ProseMirror]:break-words [&_.ProseMirror]:px-[var(--padding-x)] [&_.ProseMirror]:py-[var(--padding-y)]",
          mounted ? "" : "hidden",
        )}
      />
      {mounted ? null : (
        <textarea
          data-control-ui="chat-composer-editor"
          data-control-family="chat-composer"
          data-slot="fallback"
          aria-label={ariaLabelledby ? undefined : ariaLabel}
          aria-labelledby={ariaLabelledby}
          aria-describedby={ariaDescribedby}
          defaultValue={input.value}
          readOnly
          disabled={input.isDisabled}
          rows={2}
          placeholder={placeholder}
          className="min-h-16 w-full resize-none px-[var(--padding-x)] py-[var(--padding-y)]"
        />
      )}
      {mounted
        ? initialExtensions.map((extension) => (extension.Overlay ? <extension.Overlay key={extension.name} editor={api} /> : null))
        : null}
    </div>
  );
}

"use client";

import type { DOMOutputSpec, NodeSpec, Node as ProseMirrorNode } from "prosemirror-model";
import type { Command } from "prosemirror-state";
import type { EditorView } from "prosemirror-view";
import { useEffect } from "react";
import type { MentionItem } from "@/components/control-ui/hooks/use-chat-composer";
import type { TriggerConfig, TriggerMenuItemData } from "@/components/control-ui/hooks/use-trigger-menu";
import { isComposingKey, useTriggerMenu } from "@/components/control-ui/hooks/use-trigger-menu";
import { detectTrigger } from "@/components/control-ui/lib/trigger-detect";
import { LiveStatus } from "@/components/control-ui/ui/live-status";
import { TriggerMenu, TriggerMenuEmpty, TriggerMenuIcon, TriggerMenuItem, TriggerMenuList } from "@/components/control-ui/ui/trigger-menu";
import { spawnExitGhost } from "../ghost";
import type { ChatComposerEditorApi, ChatComposerEditorExtension } from "../types";

// Ships the "@" pill as one composable unit, so base editor stays mention-free.

// ProseMirror types attrs as `any`, so each is read through typeof guard rather than asserted
function attrString(value: unknown, fallback: string): string {
  return typeof value === "string" ? value : fallback;
}

// atom + contenteditable=false makes it one non-editable unit arrows skip over; leafText serializes it back to "@label"
const mentionNode: NodeSpec = {
  group: "inline",
  inline: true,
  atom: true,
  selectable: true,
  draggable: false,
  attrs: {
    id: { default: "" },
    label: { default: "" },
    kind: { default: "mention" },
    icon: { default: null },
  },
  parseDOM: [
    {
      tag: "span[data-mention]",
      getAttrs: (dom) => {
        if (typeof dom === "string") return false;
        return {
          id: dom.getAttribute("data-id") ?? "",
          label: dom.textContent ?? "",
          kind: dom.getAttribute("data-mention") ?? "mention",
          icon: dom.getAttribute("data-icon"),
        };
      },
    },
  ],
  toDOM: (node): DOMOutputSpec => {
    const label = attrString(node.attrs.label, "");
    const id = attrString(node.attrs.id, "");
    const kind = attrString(node.attrs.kind, "mention");
    const icon = typeof node.attrs.icon === "string" ? node.attrs.icon : null;
    const attrs = {
      class: "inline-flex items-center align-baseline",
      "data-control-ui": "chat-composer",
      "data-control-family": "chat-composer",
      "data-slot": "mention",
      "data-mention": kind,
      "data-id": id,
      "data-icon": icon ?? "",
      contenteditable: "false",
    };
    const labelSpan: DOMOutputSpec = [
      "span",
      {
        class: "truncate",
        "data-control-ui": "chat-composer",
        "data-control-family": "chat-composer",
        "data-slot": "mention-label",
      },
      label,
    ];
    return icon === null
      ? ["span", attrs, labelSpan]
      : [
          "span",
          attrs,
          [
            "img",
            {
              src: icon,
              alt: "",
              width: "16",
              height: "16",
              loading: "lazy",
              decoding: "async",
              class: "shrink-0",
              "data-control-ui": "chat-composer",
              "data-control-family": "chat-composer",
              "data-slot": "mention-icon",
            },
          ],
          labelSpan,
        ];
  },
  leafText: (node) => `@${attrString(node.attrs.label, "")}`,
};

type EditorTriggerState = {
  active: boolean;
  from: number;
  to: number;
  char: string;
  query: string;
  rect: DOMRect | null;
};

const INACTIVE: EditorTriggerState = { active: false, from: 0, to: 0, char: "", query: "", rect: null };

// reads off live view so positions are never stale
function readEditorTrigger(view: EditorView, triggerChars: readonly string[]): EditorTriggerState {
  const { selection } = view.state;
  if (!selection.empty) return INACTIVE;
  const { $from } = selection;
  if (!$from.parent.isTextblock) return INACTIVE;
  const start = $from.start();
  // atoms collapse to one sentinel char so string offsets map 1:1 onto doc positions
  const textBefore = view.state.doc.textBetween(start, $from.pos, undefined, () => "￼");
  const match = detectTrigger(textBefore, triggerChars);
  if (match === null) return INACTIVE;
  const coords = view.coordsAtPos($from.pos);
  return {
    active: true,
    from: start + match.start,
    to: $from.pos,
    char: match.char,
    query: match.query,
    rect: new DOMRect(coords.left, coords.top, 1, coords.bottom - coords.top),
  };
}

type MentionNodeAttrs = { id: string; label: string; kind?: string; icon?: string | null };

function insertMention(view: EditorView, from: number, to: number, attrs: MentionNodeAttrs) {
  const mention = view.state.schema.nodes.mention;
  if (!mention) {
    throw new Error("Mention extension requires a mention node in the editor schema.");
  }
  const node = mention.create({
    id: attrs.id,
    label: attrs.label,
    kind: attrs.kind ?? "mention",
    icon: attrs.icon ?? null,
  });
  const transaction = view.state.tr.replaceWith(from, to, node);
  transaction.insertText(" ");
  view.dispatch(transaction);
  view.focus();
}

// for slash-commands that run action instead of inserting
function deleteTriggerToken(view: EditorView, from: number, to: number) {
  view.dispatch(view.state.tr.delete(from, to));
  view.focus();
}

// must run before transaction lands, while nodeDOM can still return pill to clone
function ghostPill(view: EditorView | undefined, pillPos: number): void {
  const dom = view?.nodeDOM(pillPos);
  if (dom instanceof HTMLElement) spawnExitGhost(dom);
}

// lone atom at block end gets trailing <br>, so plain Backspace reads as adding newline rather than removing pill.
// Deleting pill and its auto-inserted space in one keystroke avoids ever leaving that lone trailing atom.
export const deleteMentionBackward: Command = (state, dispatch, view) => {
  const { selection } = state;
  if (!selection.empty) return false;
  const { $from } = selection;
  const before = $from.nodeBefore;
  if (!before) return false;
  if (before.type.name === "mention") {
    const pillPos = $from.pos - before.nodeSize;
    if (dispatch) {
      ghostPill(view, pillPos);
      dispatch(state.tr.delete(pillPos, $from.pos).scrollIntoView());
    }
    return true;
  }
  // at block end space and pill go together, or pill becomes last node and draws phantom line
  if (before.isText && before.text === " " && $from.pos === $from.end()) {
    const beforeSpace = state.doc.resolve($from.pos - before.nodeSize).nodeBefore;
    if (beforeSpace && beforeSpace.type.name === "mention") {
      const pillPos = $from.pos - before.nodeSize - beforeSpace.nodeSize;
      if (dispatch) {
        ghostPill(view, pillPos);
        dispatch(state.tr.delete(pillPos, $from.pos).scrollIntoView());
      }
      return true;
    }
  }
  return false;
};

// forward-delete symmetry with Backspace commands above
export const deleteMentionForward: Command = (state, dispatch, view) => {
  const { selection } = state;
  if (!selection.empty) return false;
  const { $from } = selection;
  const after = $from.nodeAfter;
  if (after?.type.name !== "mention") return false;
  if (dispatch) {
    ghostPill(view, $from.pos);
    dispatch(state.tr.delete($from.pos, $from.pos + after.nodeSize).scrollIntoView());
  }
  return true;
};

// ids agent consumes, ridden along on submit payload beside plain text
function collectMentions(doc: ProseMirrorNode): MentionItem[] {
  const mentions: MentionItem[] = [];
  doc.descendants((node) => {
    if (node.type.name === "mention") {
      mentions.push({
        id: attrString(node.attrs.id, ""),
        label: attrString(node.attrs.label, ""),
        kind: attrString(node.attrs.kind, "mention"),
      });
    }
  });
  return mentions;
}

type MentionOverlayProps<Item extends TriggerMenuItemData> = {
  editor: ChatComposerEditorApi;
  triggers: readonly TriggerConfig<Item>[];
  side: "top" | "bottom";
  align: "start" | "center" | "end";
  emptyLabel: string;
  resultsLabel: (count: number) => string;
};

// talks to doc only through editor api, so no ProseMirror plugin is needed and base editor stays mention-unaware
function MentionOverlay<Item extends TriggerMenuItemData>({
  editor,
  triggers,
  side,
  align,
  emptyLabel,
  resultsLabel,
}: MentionOverlayProps<Item>) {
  const chars = triggers.map((trigger) => trigger.char);

  const controller = useTriggerMenu<Item>({
    triggers,
    onCommit: (item, trigger) => {
      const view = editor.getView();
      if (!view) return;
      const state = readEditorTrigger(view, chars);
      if (!state.active) return;
      if ((trigger.insert ?? "replace") === "none") {
        deleteTriggerToken(view, state.from, state.to);
      } else {
        insertMention(view, state.from, state.to, { id: item.id, label: item.label, kind: item.kind, icon: item.image ?? null });
      }
      trigger.onSelect?.(item, { char: state.char, query: state.query });
    },
  });

  useEffect(() => {
    return editor.subscribe(() => {
      const view = editor.getView();
      if (!view) return;
      const state = readEditorTrigger(view, chars);
      controller.report(state.active ? { char: state.char, query: state.query, start: state.from, end: state.to } : null, state.rect);
    });
  }, [editor, controller, chars]);

  const { "aria-controls": controls, "aria-activedescendant": activeDescendant } = controller.inputAria;
  useEffect(() => {
    editor.setHostAria({
      "aria-autocomplete": "list",
      "aria-haspopup": "listbox",
      ...(controls ? { "aria-controls": controls } : {}),
      ...(activeDescendant ? { "aria-activedescendant": activeDescendant } : {}),
    });
  }, [editor, controls, activeDescendant]);
  useEffect(() => () => editor.setHostAria({}), [editor]);

  // open menu eats arrows, Enter, and Esc before editor's keymaps see them
  useEffect(() => {
    return editor.registerKeyHandler((event) => {
      if (isComposingKey(event)) return false;
      const view = editor.getView();
      if (!view) return false;
      if (!readEditorTrigger(view, chars).active) return false;
      return controller.handleKeyDown(event.key);
    });
  }, [editor, controller, chars]);

  if (triggers.length === 0) return null;
  const isEmpty = controller.open && controller.items.length === 0;
  let status = "";
  if (isEmpty) status = emptyLabel;
  else if (controller.open) status = resultsLabel(controller.items.length);
  return (
    <>
      <LiveStatus message={status} />
      <TriggerMenu open={controller.open} onOpenChange={controller.setOpen} anchorRect={controller.anchorRect} side={side} align={align}>
        {isEmpty ? <TriggerMenuEmpty aria-hidden="true">{emptyLabel}</TriggerMenuEmpty> : null}
        <TriggerMenuList id={controller.listId}>
          {controller.items.map((item, index) => (
            <TriggerMenuItem
              key={item.id}
              id={controller.optionId(index)}
              active={index === controller.activeIndex}
              disabled={item.disabled}
              onPointerMove={() => controller.setActiveIndex(index)}
              onClick={() => controller.select(item)}
            >
              {item.icon ? <TriggerMenuIcon>{item.icon}</TriggerMenuIcon> : null}
              <span className="flex-1 truncate" title={item.label}>
                {item.label}
              </span>
              {item.description ? (
                <span
                  data-control-ui="chat-composer"
                  data-control-family="chat-composer"
                  data-slot="mention-description"
                  className="truncate"
                  title={item.description}
                >
                  {item.description}
                </span>
              ) : null}
            </TriggerMenuItem>
          ))}
        </TriggerMenuList>
      </TriggerMenu>
    </>
  );
}

export type MentionExtensionConfig<Item extends TriggerMenuItemData = TriggerMenuItemData> = {
  triggers: readonly TriggerConfig<Item>[];
  side?: "top" | "bottom";
  align?: "start" | "center" | "end";
  /** Shown and announced when a trigger's query matches nothing. */
