"use client";

import { prefersReducedMotion } from "@/components/control-ui/lib/motion";

// ProseMirror removes nodes synchronously, so they are gone before any transition runs and @starting-style cannot cover exit.
// element is cloned into fixed-position ghost over its last rect, animated out by chat-composer-editor.css, and self-removes on animationend with timeout backstop.

// .ProseMirror is styled by scoped utilities on its mount wrapper, which body-appended clone never inherits
const MESSAGE_INHERIT = [
  "font-family",
  "font-size",
  "font-weight",
  "font-style",
  "line-height",
  "letter-spacing",
  "color",
  "padding",
  "white-space",
  "overflow-wrap",
  "word-break",
  "text-align",
] as const;

export function spawnExitGhost(source: HTMLElement, inherit: readonly string[] = []): void {
  if (typeof document === "undefined") return;
  if (prefersReducedMotion(source)) return;

  const rect = source.getBoundingClientRect();
  if (rect.width === 0 && rect.height === 0) return;

  const ghost = document.createElement(source.tagName.toLowerCase());
  // carries class and data-slot across so utility and skin styling render identically
  for (const name of source.getAttributeNames()) {
    const value = source.getAttribute(name);
    if (value !== null) ghost.setAttribute(name, value);
  }
  ghost.innerHTML = source.innerHTML;
  ghost.setAttribute("data-chat-composer-exit", "");
  ghost.setAttribute("data-exiting", "");
  ghost.setAttribute("aria-hidden", "true");
  ghost.removeAttribute("contenteditable");

  if (inherit.length > 0 && typeof getComputedStyle === "function") {
    const computed = getComputedStyle(source);
    for (const property of inherit) ghost.style.setProperty(property, computed.getPropertyValue(property));
  }

  ghost.style.position = "fixed";
  ghost.style.left = `${rect.left}px`;
  ghost.style.top = `${rect.top}px`;
  ghost.style.width = `${rect.width}px`;
  ghost.style.height = `${rect.height}px`;
  ghost.style.margin = "0";
  ghost.style.overflow = "hidden";
  ghost.style.pointerEvents = "none";
  ghost.style.zIndex = "50";

  document.body.appendChild(ghost);

  const remove = () => ghost.remove();
  ghost.addEventListener("animationend", remove, { once: true });
  window.setTimeout(remove, 600);
}

export const MESSAGE_GHOST_INHERIT = MESSAGE_INHERIT;

import type { DOMOutputSpec, NodeSpec } from "prosemirror-model";
import { Schema } from "prosemirror-model";

import type { ChatComposerEditorExtension } from "./types";

// stays mention-free — rich nodes arrive through createEditorSchema
const baseNodes: Record<string, NodeSpec> = {
  doc: { content: "block+" },
  paragraph: {
    group: "block",
    content: "inline*",
    parseDOM: [{ tag: "p" }],
    toDOM: (): DOMOutputSpec => ["p", 0],
  },
  text: { group: "inline" },
};

// later extensions win node-name collision
export function createEditorSchema(extensions: readonly ChatComposerEditorExtension[]): Schema {
  let nodes: Record<string, NodeSpec> = { ...baseNodes };
  for (const extension of extensions) {
    if (extension.nodes) nodes = { ...nodes, ...extension.nodes };
  }
  return new Schema({ nodes, marks: {} });
}

import type { Node as ProseMirrorNode, Schema } from "prosemirror-model";

// Each leaf serializes through its own schema `leafText`, so extensions stay self-describing and this stays mention-unaware.
export function serializeDoc(doc: ProseMirrorNode): string {
  return doc.textBetween(0, doc.content.size, "\n", (leaf) => {
    const leafText = leaf.type.spec.leafText;
    return typeof leafText === "function" ? leafText(leaf) : "";
  });
}

// external resets only — rebuilding doc from its own output would fight caret
export function docFromText(schema: Schema, text: string): ProseMirrorNode {
  const paragraph = schema.nodes.paragraph;
  const doc = schema.nodes.doc;
  if (!paragraph || !doc) {
    throw new Error("Chat composer schema requires doc and paragraph nodes.");
  }
  const blocks = text.split("\n").map((line) => paragraph.create(null, line === "" ? null : schema.text(line)));
  return doc.create(null, blocks.length === 0 ? paragraph.create() : blocks);
}

